extends Node
var p
var accepted_count := 0
func _ready() -> void:
	p = get_meta("viento_project")
	set_process(false)
	set_physics_process(false)
	call_deferred("_start")
func _start() -> void:
	var host = p.host.get_ref()
	host.set_process(false)
	host.flushing = true
	var q
	for actor in host.current.actors:
		if actor["instanceId"] == "bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb2":
			q = actor["node"].get_node("behavior_62626262_6262_4262_8262_000000000019").get_meta("viento_project")
	_accepted("a-play", p.play_animation())
	_accepted("b-play", q.play_animation())
	_accepted("a-pause", p.pause_animation())
	_accepted("b-stop", q.stop_animation())
	held_idle = Engine.get_process_frames()
	held_physics = Engine.get_physics_frames()
	set_process(true)
func _probe(kind: String, label: String, extra: Dictionary = {}) -> void:
	var data := {"kind": kind, "label": label, "clock": {"idleFrame": Engine.get_process_frames(), "physicsFrame": Engine.get_physics_frames()}}
	data.merge(extra)
	print("VIENTO_ANIMATION_REQUEST_PROBE:" + JSON.stringify(data))
func _accepted(label: String, accepted: bool) -> void:
	if accepted:
		accepted_count += 1
	_probe("accepted", label, {"accepted": accepted, "requestId": accepted_count if accepted else null, "reserved": p.host.get_ref().animation_control.reserved_count})
func _applied(label: String) -> void:
	_probe("applied", label, {"commandSequence": p.host.get_ref().animation_control.sequence})
func _finish() -> void:
	p.host.get_ref().finish_project()
var held_idle := 0
var held_physics := 0
func _process(_delta: float) -> void:
	if Engine.get_process_frames() <= held_idle + 3 or Engine.get_physics_frames() <= held_physics:
		return
	set_process(false)
	var host = p.host.get_ref()
	host.flushing = false
	host.flush_requests()
	_applied("later-frame")
	call_deferred("_finish")
